using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;

public static class LunarPilotBuilder {
 const string Base="Assets/LunarPilot/";
 [Serializable]public class MeshInfo {public string file;public int vertices,triangles;}
 [Serializable]public class RockType:MeshInfo {public int id;public string texture;public float sourceMean;}
 [Serializable]public class Rock {public int type;public float[] matrix;}
 [Serializable]public class Region {public string id,label;public float[] offset,focus;public float yaw,pitch;public MeshInfo[] meshes;public Rock[] rocks;public int rock_count;}
 [Serializable]public class SceneData {public Region[] regions;public RockType[] rockTypes;}
 [Serializable]public class Record {public string scene,view,material,image;public float[] position,rotation;public int width,height;public float fieldOfView;public int terrainVertices,rockInstances;}
 [Serializable]public class Report {public string status,unityVersion,gpu,graphicsAPI,colorSpace,pipeline;public bool dlss5Enabled,newTerrainDisplacement;public float sunIntensity=1.5f,sunElevationDegrees=25f,exposure=.8f;public List<Record> renders=new List<Record>();public string[] savedScenes;}
 static Dictionary<string,Mesh> meshes=new Dictionary<string,Mesh>();
 static string Output=>Path.Combine(Directory.GetParent(Application.dataPath).FullName,"Outputs");
 static Mesh LoadMesh(string file){if(meshes.TryGetValue(file,out var existing))return existing;var raw=File.ReadAllBytes(Base+file);using(var br=new BinaryReader(new MemoryStream(raw))){int n=br.ReadInt32(),ni=br.ReadInt32();var v=new Vector3[n];var ns=new Vector3[n];var uv=new Vector2[n];for(int i=0;i<n;i++)v[i]=new Vector3(br.ReadSingle(),br.ReadSingle(),br.ReadSingle());for(int i=0;i<n;i++)ns[i]=new Vector3(br.ReadSingle(),br.ReadSingle(),br.ReadSingle());for(int i=0;i<n;i++)uv[i]=new Vector2(br.ReadSingle(),br.ReadSingle());var indices=new int[ni];for(int i=0;i<ni;i++)indices[i]=br.ReadInt32();var m=new Mesh{name=Path.GetFileNameWithoutExtension(file),indexFormat=IndexFormat.UInt32};m.vertices=v;m.normals=ns;m.uv=uv;m.triangles=indices;m.RecalculateBounds();m.RecalculateTangents();string asset=Base+"Generated/"+m.name+".asset";if(File.Exists(asset))AssetDatabase.DeleteAsset(asset);AssetDatabase.CreateAsset(m,asset);meshes[file]=m;return m;}}
 static Texture2D Tex(string path)=>AssetDatabase.LoadAssetAtPath<Texture2D>(Base+path);
 static void ImportTextures(){foreach(var f in Directory.GetFiles(Base+"Textures","*",SearchOption.AllDirectories)){if(!f.EndsWith(".png")&&!f.EndsWith(".jpg"))continue;var ti=(TextureImporter)AssetImporter.GetAtPath(f.Replace('\\','/'));if(ti==null)continue;string file=Path.GetFileName(f);bool normal=file=="normal.png"||file.Contains("nor_gl")||file.Contains("normal_fine");bool data=file=="ao.png"||file=="rough.png"||file=="surface.png"||file.Contains("_AO.");ti.textureType=normal?TextureImporterType.NormalMap:TextureImporterType.Default;ti.sRGBTexture=!normal&&!data;ti.flipGreenChannel=false;ti.wrapMode=TextureWrapMode.Repeat;ti.filterMode=FilterMode.Trilinear;ti.anisoLevel=16;ti.mipmapEnabled=true;ti.maxTextureSize=2048;ti.textureCompression=TextureImporterCompression.Uncompressed;ti.SaveAndReimport();}}
 static Material[] GroundMaterials(Region r){var ids=new[]{"original","mixed","moon_01","moon_03","moon_04","moon_flat_macro_01","moon_dusted_01"};var result=new List<Material>();foreach(string id in ids){string src=id=="mixed"||id=="original"?"moon_01":id;var mat=new Material(Shader.Find("LunarPilot/Ground")){name=id};foreach(var pair in new[]{new[]{"_MainTex","moon_01_diff_2k.jpg"}}){}mat.SetTexture("_MainTex",Tex("Textures/"+src+"/"+src+"_diff_2k.jpg"));mat.SetTexture("_NormalTex",Tex("Textures/"+src+"/normal.png"));mat.SetTexture("_SurfaceTex",Tex("Textures/"+src+"/surface.png"));mat.SetTexture("_FineTex",Tex("Textures/moon_flat_macro_01/moon_flat_macro_01_diff_2k.jpg"));mat.SetTexture("_FineNormal",Tex("Textures/moon_flat_macro_01/normal.png"));mat.SetTexture("_DustTex",Tex("Textures/moon_dusted_01/moon_dusted_01_diff_2k.jpg"));mat.SetTexture("_DustNormal",Tex("Textures/moon_dusted_01/normal.png"));mat.SetTexture("_DustSurface",Tex("Textures/moon_dusted_01/surface.png"));mat.SetFloat("_Width",src=="moon_01"?3.1f:src=="moon_03"||src=="moon_04"?3.2f:.4f);mat.SetFloat("_Mixed",id=="mixed"?1:0);mat.SetFloat("_Original",id=="original"?1:0);mat.SetFloat("_Strength",.65f);mat.SetVector("_Offset",new Vector4(r.offset[0],r.offset[1],0,0));mat.SetVector("_Focus",new Vector4(r.focus[0]+r.offset[0],r.focus[2]+r.offset[1],0,0));if(id=="original"){mat.SetTexture("_MainTex",Tex("Textures/original/moon_01_Diffuse.png"));mat.SetTexture("_NormalTex",Tex("Textures/original/moon_01_nor_gl.png"));mat.SetTexture("_SurfaceTex",Tex("Textures/original/moon_01_surface.png"));mat.SetTexture("_SecondTex",Tex("Textures/original/moon_02_Diffuse.png"));mat.SetTexture("_SecondNormal",Tex("Textures/original/moon_02_nor_gl.png"));mat.SetTexture("_SecondAO",Tex("Textures/original/moon_02_AO.png"));mat.SetTexture("_LocalNormal",Tex("Textures/original/"+r.id+"_normal_fine.png"));}string path=Base+"Generated/"+r.id+"_"+id+".mat";if(File.Exists(path))AssetDatabase.DeleteAsset(path);AssetDatabase.CreateAsset(mat,path);result.Add(mat);}return result.ToArray();}
 static void SaveImage(Camera cam,string file){int w=1920,h=1080;var hdr=new RenderTexture(w,h,24,RenderTextureFormat.ARGBHalf,RenderTextureReadWrite.Linear){antiAliasing=4};var ldr=new RenderTexture(w,h,0,RenderTextureFormat.ARGB32,RenderTextureReadWrite.sRGB);hdr.Create();ldr.Create();cam.targetTexture=hdr;cam.Render();var tone=new Material(Shader.Find("LunarPilot/ACES"));tone.SetFloat("_Exposure",.8f);bool previous=GL.sRGBWrite;GL.sRGBWrite=true;Graphics.Blit(hdr,ldr,tone);GL.sRGBWrite=previous;RenderTexture.active=ldr;var image=new Texture2D(w,h,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,w,h),0,0);image.Apply();File.WriteAllBytes(file,image.EncodeToPNG());cam.targetTexture=null;RenderTexture.active=null;UnityEngine.Object.DestroyImmediate(image);UnityEngine.Object.DestroyImmediate(tone);hdr.Release();ldr.Release();UnityEngine.Object.DestroyImmediate(hdr);UnityEngine.Object.DestroyImmediate(ldr);}
 public static void Run(){try{Directory.CreateDirectory(Output+"/verification");Directory.CreateDirectory(Output+"/renders");Directory.CreateDirectory(Base+"Generated");Directory.CreateDirectory("Assets/Scenes");PlayerSettings.colorSpace=ColorSpace.Linear;QualitySettings.antiAliasing=4;QualitySettings.shadows=ShadowQuality.All;QualitySettings.shadowResolution=ShadowResolution.VeryHigh;QualitySettings.shadowDistance=100;QualitySettings.shadowCascades=4;QualitySettings.pixelLightCount=4;ShaderUtil.allowAsyncCompilation=false;AssetDatabase.Refresh();ImportTextures();var data=JsonUtility.FromJson<SceneData>(File.ReadAllText(Base+"scene_data.json"));var report=new Report{status="UNITY_RENDER_STARTED",unityVersion=Application.unityVersion,gpu=SystemInfo.graphicsDeviceName,graphicsAPI=SystemInfo.graphicsDeviceType.ToString(),colorSpace=QualitySettings.activeColorSpace.ToString(),pipeline="Unity Built-in / custom Standard PBR / linear HDR / ACES / 4x MSAA",dlss5Enabled=false,newTerrainDisplacement=false};var saved=new List<string>();
 foreach(var r in data.regions){EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);RenderSettings.skybox=null;RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=Color.white*.035f;RenderSettings.fog=false;var mats=GroundMaterials(r);var terrain=new GameObject("Original terrain / " +r.id);var ground=new List<Renderer>();int totalVertices=0;foreach(var info in r.meshes){var go=new GameObject(Path.GetFileNameWithoutExtension(info.file));go.transform.SetParent(terrain.transform);var mesh=LoadMesh(info.file);go.AddComponent<MeshFilter>().sharedMesh=mesh;var mr=go.AddComponent<MeshRenderer>();mr.sharedMaterial=mats[1];mr.shadowCastingMode=ShadowCastingMode.On;mr.receiveShadows=true;ground.Add(mr);totalVertices+=mesh.vertexCount;}
 var rocks=new GameObject("Original rock instances");var rockMats=new Dictionary<int,Material>();foreach(var t in data.rockTypes){var mat=new Material(Shader.Find("LunarPilot/Rock")){name="Rock "+t.id};mat.SetTexture("_MainTex",Tex(t.texture));mat.SetFloat("_Mean",t.sourceMean);string mp=Base+"Generated/rock_"+t.id+".mat";if(!File.Exists(mp))AssetDatabase.CreateAsset(mat,mp);else mat=AssetDatabase.LoadAssetAtPath<Material>(mp);rockMats[t.id]=mat;}
 foreach(var rec in r.rocks){var t=data.rockTypes.First(x=>x.id==rec.type);var go=new GameObject("Rock "+rec.type);go.transform.SetParent(rocks.transform);var m=new Matrix4x4();for(int c=0;c<4;c++)m.SetColumn(c,new Vector4(rec.matrix[c*4],rec.matrix[c*4+1],rec.matrix[c*4+2],rec.matrix[c*4+3]));go.transform.position=m.GetColumn(3);go.transform.rotation=m.rotation;go.transform.localScale=m.lossyScale;go.AddComponent<MeshFilter>().sharedMesh=LoadMesh(t.file);var mr=go.AddComponent<MeshRenderer>();mr.sharedMaterial=rockMats[rec.type];mr.shadowCastingMode=ShadowCastingMode.On;mr.receiveShadows=true;}
 var sun=new GameObject("Sun / 25 degrees").AddComponent<Light>();sun.type=LightType.Directional;sun.color=new Color(1,.988f,.962f);sun.intensity=1.5f;sun.shadows=LightShadows.Soft;sun.shadowStrength=1;sun.shadowBias=.015f;sun.shadowNormalBias=.03f;sun.shadowResolution=LightShadowResolution.VeryHigh;sun.transform.rotation=Quaternion.LookRotation(-new Vector3(-.6408564f,.4226183f,.6408564f),Vector3.up);RenderSettings.sun=sun;
 var cam=new GameObject("Main Camera").AddComponent<Camera>();cam.tag="MainCamera";cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=Color.black;cam.nearClipPlane=.025f;cam.farClipPlane=30000;cam.allowHDR=true;cam.allowMSAA=true;cam.fieldOfView=66;var effect=cam.gameObject.AddComponent<LunarToneEffect>();effect.toneShader=Shader.Find("LunarPilot/ACES");effect.exposure=.8f;effect.enabled=false;var focus=new Vector3(r.focus[0],r.focus[1],r.focus[2]);var target=new GameObject("Detail focus");target.transform.position=focus;var controller=new GameObject("Material preview controls").AddComponent<LunarViewer>();controller.materials=mats;controller.ground=ground.ToArray();controller.viewCamera=cam;controller.orbitTarget=target.transform;controller.sceneLabel=r.id;
 foreach(string view in new[]{"low","orbit"}){if(view=="low"){cam.transform.position=new Vector3(0,.55f,0);cam.transform.rotation=Quaternion.LookRotation(new Vector3(Mathf.Cos(r.yaw)*Mathf.Cos(r.pitch),Mathf.Sin(r.pitch),Mathf.Sin(r.yaw)*Mathf.Cos(r.pitch)),Vector3.up);cam.fieldOfView=66;}else{cam.transform.position=focus+new Vector3(Mathf.Cos(2.35f)*Mathf.Cos(.8f),Mathf.Sin(.8f),Mathf.Sin(2.35f)*Mathf.Cos(.8f))*15;cam.transform.LookAt(focus);cam.fieldOfView=52;}
 foreach(var mat in mats){foreach(var mr in ground)mr.sharedMaterial=mat;string materialId=mat.name.StartsWith(r.id+"_")?mat.name.Substring(r.id.Length+1):mat.name;string name=r.id+"_"+view+"_"+materialId+".png";SaveImage(cam,Output+"/renders/"+name);report.renders.Add(new Record{scene=r.id,view=view,material=materialId,image="renders/"+name,width=1920,height=1080,fieldOfView=cam.fieldOfView,terrainVertices=totalVertices,rockInstances=r.rocks.Length,position=new[]{cam.transform.position.x,cam.transform.position.y,cam.transform.position.z},rotation=new[]{cam.transform.rotation.x,cam.transform.rotation.y,cam.transform.rotation.z,cam.transform.rotation.w}});Debug.Log("LUNAR_RENDERED "+name);}}
 foreach(var mr in ground)mr.sharedMaterial=mats[1];cam.transform.position=new Vector3(0,.55f,0);cam.transform.rotation=Quaternion.LookRotation(new Vector3(Mathf.Cos(r.yaw)*Mathf.Cos(r.pitch),Mathf.Sin(r.pitch),Mathf.Sin(r.yaw)*Mathf.Cos(r.pitch)),Vector3.up);cam.fieldOfView=66;effect.enabled=true;string scenePath="Assets/Scenes/"+r.id+".unity";EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),scenePath);saved.Add(scenePath);AssetDatabase.SaveAssets();}
 report.savedScenes=saved.ToArray();report.status="UNITY_RENDER_COMPLETE";File.WriteAllText(Output+"/verification/unity_render_report.json",JsonUtility.ToJson(report,true));Debug.Log("LUNAR_PILOT_COMPLETE "+report.renders.Count);AssetDatabase.SaveAssets();EditorApplication.Exit(0);
 }catch(Exception ex){Directory.CreateDirectory(Output+"/verification");File.WriteAllText(Output+"/verification/unity_error.txt",ex.ToString());Debug.LogException(ex);EditorApplication.Exit(1);}}
}


